CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role;
CREATE SCHEMA auth; CREATE SCHEMA smarter_private;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$SELECT nullif(current_setting('test.viewer',true),'')::uuid$$;
CREATE FUNCTION public.ca_club_roster_access(uuid,uuid) RETURNS text LANGUAGE sql STABLE AS $$SELECT coalesce(nullif(current_setting('test.access',true),''),'service')$$;
CREATE FUNCTION public.fn_club_scope_ids(uuid) RETURNS uuid[] LANGUAGE sql STABLE AS $$SELECT ARRAY[$1]$$;
CREATE FUNCTION public.fn_club_role_rank(text) RETURNS integer LANGUAGE sql IMMUTABLE AS $$SELECT 1$$;
CREATE FUNCTION public.fn_arena_name(text,text,text,text,text,text) RETURNS text LANGUAGE sql IMMUTABLE AS $$SELECT coalesce($1,$2)$$;
CREATE FUNCTION public.fn_ca_fee_counting_start() RETURNS date LANGUAGE sql IMMUTABLE AS $$SELECT date '2026-10-12'$$;
CREATE FUNCTION public.fn_ca_launch_accounting_cutoff(text,uuid) RETURNS timestamptz LANGUAGE sql STABLE AS $$SELECT nullif(current_setting('test.cutoff',true),'')::timestamptz$$;
CREATE FUNCTION public.fn_ca_launch_accounting_accepts(uuid,timestamptz) RETURNS boolean LANGUAGE sql STABLE AS $$SELECT $2>=coalesce(public.fn_ca_launch_accounting_cutoff('club',$1),'-infinity'::timestamptz)$$;
CREATE TABLE club_member_daily_facts(club_id uuid,user_id uuid,played_on date,game_variant text,is_mtt boolean,hands bigint,wins bigint,vpip_hands bigint,pfr_hands bigint,tb_hands bigint,faced_tb bigint,folded_tb bigint,cb_hands bigint,cb_opps bigint,fees numeric,net numeric);
CREATE TABLE member_record_daily_facts(LIKE club_member_daily_facts,accounting_cutoff timestamptz);
CREATE TABLE club_member_daily_facts_state(singleton boolean,initialized boolean); INSERT INTO club_member_daily_facts_state VALUES(true,true);
CREATE TABLE ca_hand_facts(hand_id uuid,user_id uuid,club_id uuid,table_id uuid,tournament_id uuid,played_at timestamptz,game_variant text,net numeric,rake_paid numeric,vpip boolean,pfr boolean,three_bet boolean,faced_three_bet boolean,folded_to_three_bet boolean,cbet_flop boolean,had_cbet_flop_opp boolean);
CREATE INDEX ON ca_hand_facts(user_id,played_at);
CREATE FUNCTION public.fn_member_record_fact_club(ca_hand_facts) RETURNS uuid LANGUAGE sql STABLE AS $$SELECT $1.club_id$$;
CREATE TABLE rake_records(id uuid,created_at timestamptz);
CREATE TABLE rake_attributions(id uuid,club_id uuid,player_id uuid,rake_record_id uuid,created_at timestamptz,rake_amount numeric);
CREATE TABLE ca_club_rake_daily_user(club_id uuid,user_id uuid,day date,rake_cents bigint);
CREATE TABLE ca_club_member_tournament_fee_daily(club_id uuid,user_id uuid,day date,fees numeric);
CREATE TABLE accounting_tournament_fee_sources(club_id uuid,player_id uuid,charged_at timestamptz,rake_credit numeric,tournament_id uuid);
CREATE TABLE smarter_private.player_fee_redemptions(club_id uuid,user_id uuid,effective_on date,amount_cents bigint);
CREATE TABLE smarter_private.player_rake_share_rules(rule_key text,club_id uuid,from_user uuid,to_user uuid,share_bps integer,effective_from timestamptz,effective_until timestamptz);
CREATE TABLE club_members(user_id uuid,club_id uuid,role text,agent_id uuid,chip_balance numeric,promo_balance numeric,nickname text,notes text,display_name text,joined_at timestamptz,last_active_at timestamptz,status text);
CREATE TABLE profiles(id uuid,player_number text,alias text,username text,display_name text,first_name text,last_name text,full_name text,arena_avatar_url text,avatar_url text,last_login timestamptz,last_seen timestamptz,is_online boolean,status text);
CREATE TABLE clubs(id uuid,name text);
CREATE TABLE agents(user_id uuid,club_id uuid,agent_wallet_balance numeric,promo_wallet_balance numeric,status text);
CREATE TABLE tables(id uuid,status text,club_id uuid);
CREATE TABLE table_seats(table_id uuid,user_id uuid,left_at timestamptz,club_id uuid);
CREATE TABLE chip_transactions(club_id uuid,to_user_id uuid,from_user_id uuid,transaction_type text,amount numeric,created_at timestamptz);
CREATE TABLE chip_ledger(club_id uuid,to_entity_id uuid,from_entity_id uuid,to_type text,from_type text,tournament_id uuid,status text,amount numeric,created_at timestamptz);
CREATE TABLE tournaments(id uuid,game_type text);
CREATE TABLE test_money(club_id uuid,user_id uuid,created_at timestamptz,amount numeric);
CREATE FUNCTION ca_club_member_tournament_money(uuid,uuid,timestamptz,timestamptz) RETURNS numeric LANGUAGE sql STABLE AS $$SELECT coalesce(sum(amount),0) FROM test_money WHERE club_id=$1 AND user_id=$2 AND ($3 IS NULL OR created_at >= $3) AND ($4 IS NULL OR created_at<$4)$$;
CREATE FUNCTION ca_club_member_jackpot_money(uuid,uuid,timestamptz,timestamptz,text DEFAULT NULL) RETURNS numeric LANGUAGE sql STABLE AS $$SELECT 0::numeric$$;
